// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, string calldata description) public {
        vm.assume(bytes(description).length <= 256);
        // jojoTeam is unset, hence address(0); the authorized caller must equal it.
        vm.prank(actor);
        bool ok = true;
        try c.newEmergencyOracle(description) {
            ok = true;
        } catch {
            ok = false;
        }
        // Universal rule: for every admissible caller the call succeeds iff the caller
        // is the JOJO team, and on success the event's owner argument is the caller
        // (msg.sender).  The mutant swaps in jojoTeam, so for any caller whose event
        // path is exercised the emitted owner differs from msg.sender.
        assertTrue(ok == (actor == c.jojoTeam()));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    event NewEmergencyOracle(address indexed owner, address indexed newOracle);

    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, string memory description) public {
        // Admissible domain: any non-zero would-be deployer; the jojo team itself is address(0).
        vm.assume(caller != address(0));

        // Rule 1: for ANY caller other than the jojo team (address(0)), the call must revert.
        vm.prank(caller);
        bool ok;
        try c.newEmergencyOracle(description) { ok = true; } catch { ok = false; }
        assertTrue(!ok, "only the jojo team (address(0)) may deploy an emergency oracle");

        // Rule 2: when the jojo team (address(0)) does deploy, the emitted
        // NewEmergencyOracle event carries owner == msg.sender == c.jojoTeam() == address(0).
        vm.prank(address(0));
        vm.expectEmit(true, true, false, address(c));
        emit NewEmergencyOracle(address(0), address(0));
        bool ok2;
        try c.newEmergencyOracle(description) { ok2 = true; } catch { ok2 = false; }
        assertTrue(ok2, "the jojo team must be able to deploy an emergency oracle");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, string calldata description) public {
        // Keep the domain wide: any actor may attempt creation; the access rule decides.
        // Drive c through its public entry newEmergencyOracle.
        vm.prank(actor);
        bool ok;
        try c.newEmergencyOracle(description) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: a non-jojoTeam caller is rejected, and an admitted caller
        // (necessarily equal to c.jojoTeam(), which is address(0) here) gets an oracle
        // whose owner() equals the caller. The mutant emits jojoTeam as the owner
        // argument instead of msg.sender, so attribution breaks for callers that
        // differ from jojoTeam whenever the team address is a distinct caller.
        assertTrue(ok == (actor == c.jojoTeam()) && (!ok || C(c).jojoTeam() == actor));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IEmergencyOracle {
    function owner() external view returns (address);
}

contract InvMutTest is Test {
    C c;
    event NewEmergencyOracle(address owner, address newOracle);

    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, string calldata description) public {
        // Admissible domain: any caller at all; success is possible only when the caller is
        // the JOJO team, so we record whether the call succeeded and only then check the
        // attribution rule. The domain stays wide: every address is tried.
        vm.prank(caller);
        (bool ok, bytes memory ret) = address(c).call(
            abi.encodeWithSelector(c.newEmergencyOracle.selector, description)
        );

        if (!ok) {
            // For non-JOJO-team callers the call must revert; nothing else to check.
            assertTrue(true);
        } else {
            // A successful call must emit NewEmergencyOracle whose owner argument is the
            // CALLER (msg.sender), not the stored jojoTeam address, and the emitted oracle
            // must be a contract owned by the caller.
            Vm.Log[] memory entries = vm.getRecordedLogs(address(c));
            bytes32 sig = keccak256("NewEmergencyOracle(address,address)");
            bool found = false;
            address emittedOwner;
            address emittedOracle;
            for (uint256 i = 0; i < entries.length; i++) {
                if (entries[i].topics[0] == sig) {
                    (emittedOwner, emittedOracle) = abi.decode(entries[i].data, (address, address));
                    found = true;
                }
            }
            assertTrue(found && emittedOwner == caller && emittedOracle != address(0) && IEmergencyOracle(emittedOracle).owner() == caller);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function testNewEmergencyOracle(string calldata description) public {
        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(c.newEmergencyOracle.selector, description)
        );
        assert(!ok);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public {
        require(true, "");
        bool reverted; try c.newEmergencyOracle("desc") { reverted = false; } catch { reverted = true; }
        assert(reverted == (address(this) != c.jojoTeam()));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(string calldata description) public payable {
        require(c.jojoTeam() != msg.sender);
        bool reverted; try c.newEmergencyOracle(description) { reverted = false; } catch { reverted = true; }   // boundary
        assert(reverted);
    }
    receive() external payable { }
}
